	var dm := Color(0.64, 0.66, 0.72) if not afford else Color.WHITE
	# host _item_card_style(tier, selected)
	var bg := Color(0.1, 0.12, 0.2, 0.96) if sel else Color(0.04, 0.06, 0.1, 0.9)
